export interface InputProps
  extends React.InputHTMLAttributes<HTMLInputElement> {
  shortcut?: string;
}

const Input = React.forwardRef<HTMLInputElement, InputProps>(
  ({ className, type, shortcut, ...props }, ref) => {
    if (shortcut) {
      return (
        <div className="relative flex items-center w-full">
          <input
            type={type}
            className={cn(
              "flex h-9 w-full rounded-md border border-input bg-background px-3 py-1 pr-12 text-sm shadow-xs transition-colors file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-hidden focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50",
