          ▲ {score}
        </span>
      );
    }
    if (lower === "low" || lower === "poor" || lower === "high complexity" || lower === "high cost") {
      return (
        <span className="inline-flex items-center gap-1 font-mono text-xs font-bold px-2 py-0.5 rounded bg-rose-500/10 text-rose-500">
