                    <p className="px-3 font-mono text-[0.7rem] font-semibold text-muted-foreground uppercase tracking-wider mb-2">
                      {group.title}
                    </p>
                  )}
                  {group.links.map((link) => (
                    <a
                      key={link.href}
                      href={link.href}
                      target={link.external ? "_blank" : undefined}
                      rel={link.external ? "noopener noreferrer" : undefined}
                      title={collapsed ? link.label : undefined}
                      className={cn(
                        "flex items-center rounded-md px-3 py-2 text-sm font-medium transition-colors hover:bg-muted",
                        link.active
                          ? "bg-muted text-primary font-semibold"
                          : "text-muted-foreground hover:text-foreground",
                        collapsed && "justify-center px-2"
                      )}
                    >
                      {renderLinkIcon(link.icon)}
                      {!collapsed && <span>{link.label}</span>}
                      {!collapsed && link.badge && (
                        <span className="ml-auto">{link.badge}</span>
                      )}
                    </a>
                  ))}
