import * as React from "react";
import { cn } from "@/lib/utils";

export interface DataPoint {
  date: string;
  [key: string]: string | number;
}

export interface AreaChartProps {
  data: DataPoint[];
  categories: string[];
  index: string;
  colors?: ("primary" | "emerald" | "amber" | "rose" | "cyan")[];
  valueFormatter?: (value: number) => string;
  height?: number;
  showGrid?: boolean;
  showLegend?: boolean;
  className?: string;
}

export interface BarChartProps {
  data: DataPoint[];
  categories: string[];
  index: string;
  colors?: ("primary" | "emerald" | "amber" | "rose" | "cyan")[];
  valueFormatter?: (value: number) => string;
  height?: number;
  showGrid?: boolean;
  showLegend?: boolean;
  className?: string;
}

export interface SparklineProps {
  data: number[];
  color?: "primary" | "emerald" | "amber" | "rose" | "cyan";
  height?: number;
  width?: number;
  className?: string;
}

const COLOR_MAP: Record<string, { stroke: string; fill: string }> = {
  primary: { stroke: "var(--primary, #e5000f)", fill: "rgba(229, 0, 15, 0.12)" },
  emerald: { stroke: "#10b981", fill: "rgba(16, 185, 129, 0.12)" },
  amber: { stroke: "#d97706", fill: "rgba(217, 119, 6, 0.12)" },
  rose: { stroke: "#dc2626", fill: "rgba(220, 38, 38, 0.12)" },
  cyan: { stroke: "#0891b2", fill: "rgba(8, 145, 178, 0.12)" },
};

export function AreaChart({
  data = [],
  categories = [],
  index,
  colors = ["primary", "emerald", "amber"],
  valueFormatter = (val) => String(val),
  height = 240,
  showGrid = true,
  showLegend = true,
  className,
}: AreaChartProps) {
  const [hoverIndex, setHoverIndex] = React.useState<number | null>(null);
  const svgRef = React.useRef<SVGSVGElement>(null);

  if (!data || data.length === 0) {
    return (
      <div
        className={cn("flex items-center justify-center border border-dashed border-border rounded-lg text-xs text-muted-foreground", className)}
        style={{ height }}
      >
        No telemetry data
      </div>
    );
  }

  const padLeft = 48;
  const padRight = 16;
  const padTop = 16;
  const padBottom = 28;
  const width = 600;

  const chartW = width - padLeft - padRight;
  const chartH = height - padTop - padBottom;

  let maxVal = 0;
  for (const row of data) {
    for (const cat of categories) {
      const val = Number(row[cat]) || 0;
      if (val > maxVal) maxVal = val;
    }
  }
  if (maxVal === 0) maxVal = 10;
  maxVal = Math.ceil(maxVal * 1.1);

  const getX = (idx: number) => {
    if (data.length <= 1) return padLeft + chartW / 2;
    return padLeft + (idx / (data.length - 1)) * chartW;
  };

  const getY = (val: number) => {
    return padTop + chartH - (val / maxVal) * chartH;
  };

  const gridSteps = 4;
  const yTicks = Array.from({ length: gridSteps + 1 }, (_, i) => {
    const val = (maxVal / gridSteps) * (gridSteps - i);
    return { val, y: padTop + (i / gridSteps) * chartH };
  });

  return (
    <div className={cn("flex flex-col w-full", className)}>
      {showLegend && (
        <div className="flex items-center gap-4 mb-2 font-mono text-xs">
          {categories.map((cat, i) => {
            const colorKey = colors[i % colors.length] || "primary";
            const c = COLOR_MAP[colorKey] || COLOR_MAP.primary;
            return (
              <div key={cat} className="flex items-center gap-1.5">
                <span className="h-2 w-2 rounded-full" style={{ backgroundColor: c.stroke }} />
                <span className="text-muted-foreground">{cat}</span>
              </div>
            );
          })}
        </div>
      )}

      <div className="relative w-full" style={{ height }}>
        <svg
          ref={svgRef}
          viewBox={`0 0 ${width} ${height}`}
          preserveAspectRatio="none"
          className="w-full h-full overflow-visible"
          onMouseMove={(e) => {
            if (!svgRef.current) return;
            const rect = svgRef.current.getBoundingClientRect();
            const relX = ((e.clientX - rect.left) / rect.width) * width;
            let closest = 0;
            let minDiff = Infinity;
            for (let i = 0; i < data.length; i++) {
              const diff = Math.abs(getX(i) - relX);
              if (diff < minDiff) {
                minDiff = diff;
                closest = i;
              }
            }
            setHoverIndex(closest);
          }}
          onMouseLeave={() => setHoverIndex(null)}
        >
          {showGrid &&
            yTicks.map((tick, i) => (
              <g key={i}>
                <line
                  x1={padLeft}
                  y1={tick.y}
                  x2={width - padRight}
                  y2={tick.y}
                  stroke="currentColor"
                  className="text-border"
                  strokeDasharray="3 3"
                />
                <text
                  x={padLeft - 8}
                  y={tick.y + 4}
                  textAnchor="end"
                  className="font-mono text-[9px] fill-muted-foreground"
                >
                  {valueFormatter(Math.round(tick.val))}
                </text>
              </g>
            ))}

          {categories.map((cat, i) => {
            const colorKey = colors[i % colors.length] || "primary";
            const c = COLOR_MAP[colorKey] || COLOR_MAP.primary;
            const points = data.map((d, idx) => ({
              x: getX(idx),
              y: getY(Number(d[cat]) || 0),
            }));

            if (points.length === 0) return null;

            const lineD = points.reduce(
              (acc, pt, idx) => (idx === 0 ? `M ${pt.x} ${pt.y}` : `${acc} L ${pt.x} ${pt.y}`),
              ""
            );
            const areaD = `${lineD} L ${points[points.length - 1].x} ${padTop + chartH} L ${points[0].x} ${padTop + chartH} Z`;

            return (
              <g key={cat}>
                <defs>
                  <linearGradient id={`reg-grad-${cat}-${i}`} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={c.stroke} stopOpacity="0.25" />
                    <stop offset="100%" stopColor={c.stroke} stopOpacity="0.0" />
                  </linearGradient>
                </defs>
                <path d={areaD} fill={`url(#reg-grad-${cat}-${i})`} />
                <path d={lineD} fill="none" stroke={c.stroke} strokeWidth="2" strokeLinecap="round" />
              </g>
            );
          })}

          {data.length > 0 && (
            <>
              <text x={getX(0)} y={height - 8} textAnchor="start" className="font-mono text-[9px] fill-muted-foreground">
                {String(data[0][index] || "")}
              </text>
              <text x={getX(data.length - 1)} y={height - 8} textAnchor="end" className="font-mono text-[9px] fill-muted-foreground">
                {String(data[data.length - 1][index] || "")}
              </text>
            </>
          )}

          {hoverIndex !== null && data[hoverIndex] && (
            <g>
              <line
                x1={getX(hoverIndex)}
                y1={padTop}
                x2={getX(hoverIndex)}
                y2={padTop + chartH}
                stroke="currentColor"
                className="text-border"
                strokeDasharray="2 2"
              />
            </g>
          )}
        </svg>

        {hoverIndex !== null && data[hoverIndex] && (
          <div
            className="absolute top-2 z-20 pointer-events-none rounded-md border border-border bg-popover p-2 text-xs shadow-md"
            style={{
              left: `${(getX(hoverIndex) / width) * 100}%`,
              transform: hoverIndex > data.length / 2 ? "translate(-105%, 10%)" : "translate(10%, 10%)",
            }}
          >
            <div className="font-mono font-semibold text-muted-foreground border-b border-border pb-1 mb-1">
              {String(data[hoverIndex][index] || "")}
            </div>
            {categories.map((cat, i) => {
              const colorKey = colors[i % colors.length] || "primary";
              const c = COLOR_MAP[colorKey] || COLOR_MAP.primary;
              return (
                <div key={cat} className="flex items-center gap-2">
                  <span className="h-1.5 w-1.5 rounded-full" style={{ backgroundColor: c.stroke }} />
                  <span className="text-foreground">{cat}:</span>
                  <span className="font-mono font-bold text-foreground">
                    {valueFormatter(Number(data[hoverIndex][cat]) || 0)}
                  </span>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

export function BarChart({
  data = [],
  categories = [],
  index,
  colors = ["primary", "emerald", "amber"],
  valueFormatter = (val) => String(val),
  height = 240,
  showGrid = true,
  showLegend = true,
  className,
}: BarChartProps) {
  if (!data || data.length === 0) {
    return (
      <div
        className={cn("flex items-center justify-center border border-dashed border-border rounded-lg text-xs text-muted-foreground", className)}
        style={{ height }}
      >
        No telemetry data
      </div>
    );
  }

  const padLeft = 48;
  const padRight = 16;
  const padTop = 16;
  const padBottom = 28;
  const width = 600;

  const chartW = width - padLeft - padRight;
  const chartH = height - padTop - padBottom;

  let maxVal = 0;
  for (const row of data) {
    for (const cat of categories) {
      const val = Number(row[cat]) || 0;
      if (val > maxVal) maxVal = val;
    }
  }
  if (maxVal === 0) maxVal = 10;
  maxVal = Math.ceil(maxVal * 1.15);

  const groupWidth = chartW / data.length;
  const barPadding = 0.2;
  const availableBarWidth = groupWidth * (1 - barPadding);
  const barWidth = Math.max(2, availableBarWidth / categories.length);

  const getY = (val: number) => padTop + chartH - (val / maxVal) * chartH;

  return (
    <div className={cn("flex flex-col w-full", className)}>
      {showLegend && (
        <div className="flex items-center gap-4 mb-2 font-mono text-xs">
          {categories.map((cat, i) => {
            const colorKey = colors[i % colors.length] || "primary";
            const c = COLOR_MAP[colorKey] || COLOR_MAP.primary;
            return (
              <div key={cat} className="flex items-center gap-1.5">
                <span className="h-2 w-2 rounded-full" style={{ backgroundColor: c.stroke }} />
                <span className="text-muted-foreground">{cat}</span>
              </div>
            );
          })}
        </div>
      )}

      <div className="relative w-full" style={{ height }}>
        <svg viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none" className="w-full h-full overflow-visible">
          {data.map((row, groupIdx) => {
            const groupX = padLeft + groupIdx * groupWidth + (groupWidth * barPadding) / 2;
            return (
              <g key={groupIdx}>
                {categories.map((cat, catIdx) => {
                  const colorKey = colors[catIdx % colors.length] || "primary";
                  const c = COLOR_MAP[colorKey] || COLOR_MAP.primary;
                  const val = Number(row[cat]) || 0;
                  const barX = groupX + catIdx * barWidth;
                  const barY = getY(val);
                  const barH = padTop + chartH - barY;

                  return (
                    <rect
                      key={cat}
                      x={barX}
                      y={barY}
                      width={Math.max(1, barWidth - 1)}
                      height={Math.max(0, barH)}
                      fill={c.stroke}
                      rx="1"
                    />
                  );
                })}
                <text x={groupX + availableBarWidth / 2} y={height - 8} textAnchor="middle" className="font-mono text-[9px] fill-muted-foreground">
                  {String(row[index] || "")}
                </text>
              </g>
            );
          })}
        </svg>
      </div>
    </div>
  );
}

export function Sparkline({
  data = [],
  color = "primary",
  height = 32,
  width = 96,
  className,
}: SparklineProps) {
  if (!data || data.length < 2) return null;

  const strokeColor = COLOR_MAP[color]?.stroke || COLOR_MAP.primary.stroke;
  const padding = 2;
  const drawW = width - padding * 2;
  const drawH = height - padding * 2;

  const min = Math.min(...data);
  const max = Math.max(...data);
  const range = max - min || 1;

  const points = data.map((val, idx) => ({
    x: padding + (idx / (data.length - 1)) * drawW,
    y: padding + drawH - ((val - min) / range) * drawH,
  }));

  const lineD = points.reduce((acc, pt, idx) => (idx === 0 ? `M ${pt.x} ${pt.y}` : `${acc} L ${pt.x} ${pt.y}`), "");
  const lastPt = points[points.length - 1];

  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} className={cn("overflow-visible inline-block", className)}>
      <path d={lineD} fill="none" stroke={strokeColor} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
      <circle cx={lastPt.x} cy={lastPt.y} r="2.5" fill={strokeColor} />
    </svg>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export interface DateRange {
  from?: Date;
  to?: Date;
}

export interface DatePickerProps {
  value?: Date;
  onChange: (date: Date) => void;
  placeholder?: string;
  className?: string;
}

export interface DateRangePickerProps {
  value?: DateRange;
  onChange: (range: DateRange) => void;
  presets?: Array<{ label: string; range: DateRange }>;
  placeholder?: string;
  className?: string;
}

function formatDate(d?: Date) {
  if (!d) return "";
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

const MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

export function DatePicker({
  value,
  onChange,
  placeholder = "Pick a date",
  className,
}: DatePickerProps) {
  const [isOpen, setIsOpen] = React.useState(false);
  const [viewDate, setViewDate] = React.useState(() => value ? new Date(value) : new Date());
  const ref = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    if (!isOpen) return;
    const handleClick = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, [isOpen]);

  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDay = new Date(year, month, 1).getDay();

  return (
    <div ref={ref} className={cn("relative inline-block", className)}>
      <button
        type="button"
        className={cn(
          "inline-flex h-9 items-center gap-2 rounded-md border border-input bg-background px-3 py-1 font-mono text-xs shadow-xs hover:bg-muted",
          isOpen && "ring-1 ring-ring"
        )}
        onClick={() => setIsOpen(!isOpen)}
      >
        <span>📅</span>
        <span className={value ? "text-foreground font-semibold" : "text-muted-foreground"}>
          {value ? formatDate(value) : placeholder}
        </span>
      </button>

      {isOpen && (
        <div className="absolute top-full mt-1 left-0 z-50 rounded-md border border-border bg-popover p-3 shadow-md animate-in fade-in-0">
          <div className="flex items-center justify-between mb-2">
            <button
              type="button"
              className="h-6 w-6 rounded border border-border flex items-center justify-center text-xs"
              onClick={() => setViewDate(new Date(year, month - 1, 1))}
            >
              ‹
            </button>
            <span className="font-heading text-xs font-semibold">
              {MONTH_NAMES[month]} {year}
            </span>
            <button
              type="button"
              className="h-6 w-6 rounded border border-border flex items-center justify-center text-xs"
              onClick={() => setViewDate(new Date(year, month + 1, 1))}
            >
              ›
            </button>
          </div>

          <div className="grid grid-cols-7 gap-1 text-center font-mono text-xs">
            {["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map((d) => (
              <span key={d} className="text-muted-foreground text-[10px] py-1">{d}</span>
            ))}
            {Array.from({ length: firstDay }).map((_, i) => (
              <span key={`empty-${i}`} />
            ))}
            {Array.from({ length: daysInMonth }).map((_, i) => {
              const day = i + 1;
              const isSelected = value && value.getFullYear() === year && value.getMonth() === month && value.getDate() === day;
              return (
                <button
                  key={day}
                  type="button"
                  className={cn(
                    "h-7 w-7 rounded-xs text-xs flex items-center justify-center hover:bg-accent",
                    isSelected && "bg-primary text-white font-bold"
                  )}
                  onClick={() => {
                    onChange(new Date(year, month, day));
                    setIsOpen(false);
                  }}
                >
                  {day}
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

export function DateRangePicker({
  value,
  onChange,
  presets,
  placeholder = "Select date range...",
  className,
}: DateRangePickerProps) {
  const [isOpen, setIsOpen] = React.useState(false);
  const [selectingFrom, setSelectingFrom] = React.useState<Date | undefined>(value?.from);
  const [viewDate, setViewDate] = React.useState(() => value?.from ? new Date(value.from) : new Date());
  const ref = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    if (!isOpen) return;
    const handleClick = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setIsOpen(false);
    };
    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, [isOpen]);

  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDay = new Date(year, month, 1).getDay();

  const handleDayClick = (day: number) => {
    const clicked = new Date(year, month, day);
    if (!selectingFrom || (value?.from && value?.to)) {
      setSelectingFrom(clicked);
      onChange({ from: clicked, to: undefined });
    } else {
      if (clicked < selectingFrom) {
        onChange({ from: clicked, to: selectingFrom });
      } else {
        onChange({ from: selectingFrom, to: clicked });
      }
      setSelectingFrom(undefined);
      setIsOpen(false);
    }
  };

  const displayText = value?.from && value?.to
    ? `${formatDate(value.from)} → ${formatDate(value.to)}`
    : value?.from
    ? `${formatDate(value.from)} → ...`
    : placeholder;

  return (
    <div ref={ref} className={cn("relative inline-block", className)}>
      <button
        type="button"
        className={cn(
          "inline-flex h-9 items-center gap-2 rounded-md border border-input bg-background px-3 py-1 font-mono text-xs shadow-xs hover:bg-muted",
          isOpen && "ring-1 ring-ring"
        )}
        onClick={() => setIsOpen(!isOpen)}
      >
        <span>📅</span>
        <span className={value?.from ? "text-foreground font-semibold" : "text-muted-foreground"}>
          {displayText}
        </span>
      </button>

      {isOpen && (
        <div className="absolute top-full mt-1 left-0 z-50 rounded-md border border-border bg-popover p-3 shadow-md animate-in fade-in-0 flex gap-3">
          <div className="flex flex-col gap-1 border-r border-border pr-3">
            {[
              { label: "Today", get: () => ({ from: new Date(), to: new Date() }) },
              { label: "Last 7d", get: () => { const to = new Date(); const from = new Date(); from.setDate(to.getDate() - 7); return { from, to }; } },
              { label: "Last 30d", get: () => { const to = new Date(); const from = new Date(); from.setDate(to.getDate() - 30); return { from, to }; } },
            ].map((p) => (
              <button
                key={p.label}
                type="button"
                className="text-left font-mono text-xs px-2 py-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground"
                onClick={() => {
                  onChange(p.get());
                  setIsOpen(false);
                }}
              >
                {p.label}
              </button>
            ))}
          </div>

          <div>
            <div className="flex items-center justify-between mb-2">
              <button
                type="button"
                className="h-6 w-6 rounded border border-border flex items-center justify-center text-xs"
                onClick={() => setViewDate(new Date(year, month - 1, 1))}
              >
                ‹
              </button>
              <span className="font-heading text-xs font-semibold">
                {MONTH_NAMES[month]} {year}
              </span>
              <button
                type="button"
                className="h-6 w-6 rounded border border-border flex items-center justify-center text-xs"
                onClick={() => setViewDate(new Date(year, month + 1, 1))}
              >
                ›
              </button>
            </div>

            <div className="grid grid-cols-7 gap-1 text-center font-mono text-xs">
              {["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map((d) => (
                <span key={d} className="text-muted-foreground text-[10px] py-1">{d}</span>
              ))}
              {Array.from({ length: firstDay }).map((_, i) => (
                <span key={`empty-${i}`} />
              ))}
              {Array.from({ length: daysInMonth }).map((_, i) => {
                const day = i + 1;
                const thisDate = new Date(year, month, day);
                const isFrom = value?.from && formatDate(thisDate) === formatDate(value.from);
                const isTo = value?.to && formatDate(thisDate) === formatDate(value.to);
                const inRange = value?.from && value?.to && thisDate > value.from && thisDate < value.to;

                return (
                  <button
                    key={day}
                    type="button"
                    className={cn(
                      "h-7 w-7 rounded-xs text-xs flex items-center justify-center hover:bg-accent",
                      (isFrom || isTo) && "bg-primary text-white font-bold",
                      inRange && "bg-primary/10 text-primary"
                    )}
                    onClick={() => handleDayClick(day)}
                  >
                    {day}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export interface DataTableColumn<T> {
  header: React.ReactNode;
  accessor?: keyof T;
  render?: (row: T, index: number) => React.ReactNode;
  sortable?: boolean;
  align?: "left" | "center" | "right";
  width?: string | number;
}

export interface DataTableProps<T = any> {
  data: T[];
  columns: DataTableColumn<T>[];
  keyField?: keyof T;
  searchable?: boolean;
  searchPlaceholder?: string;
  selectable?: boolean;
  selectedKeys?: any[];
  onSelectedKeysChange?: (keys: any[]) => void;
  renderBulkActions?: (selectedRows: T[]) => React.ReactNode;
  pageSize?: number;
  dense?: boolean;
  emptyText?: string;
  className?: string;
}

export function DataTable<T extends Record<string, any>>({
  data = [],
  columns = [],
  keyField = "id" as keyof T,
  searchable = true,
  searchPlaceholder = "Search...",
  selectable = false,
  selectedKeys: controlledSelectedKeys,
  onSelectedKeysChange,
  renderBulkActions,
  pageSize = 10,
  dense = false,
  emptyText = "No records found",
  className,
}: DataTableProps<T>) {
  const [internalSelectedKeys, setInternalSelectedKeys] = React.useState<any[]>([]);
  const [search, setSearch] = React.useState("");
  const [sortKey, setSortKey] = React.useState<keyof T | null>(null);
  const [sortDir, setSortDir] = React.useState<"asc" | "desc" | null>(null);
  const [currentPage, setCurrentPage] = React.useState(1);

  const selectedKeys = controlledSelectedKeys !== undefined ? controlledSelectedKeys : internalSelectedKeys;

  const setSelectedKeys = (keys: any[]) => {
    if (onSelectedKeysChange) onSelectedKeysChange(keys);
    else setInternalSelectedKeys(keys);
  };

  const filteredData = React.useMemo(() => {
    if (!search.trim()) return data;
    const q = search.toLowerCase();
    return data.filter((row) =>
      columns.some((col) => {
        if (!col.accessor) return false;
        const val = row[col.accessor];
        return val !== null && val !== undefined && String(val).toLowerCase().includes(q);
      })
    );
  }, [data, search, columns]);

  const sortedData = React.useMemo(() => {
    if (!sortKey || !sortDir) return filteredData;
    return [...filteredData].sort((a, b) => {
      const valA = a[sortKey];
      const valB = b[sortKey];
      if (valA === valB) return 0;
      if (valA === null || valA === undefined) return 1;
      if (valB === null || valB === undefined) return -1;
      let comp = 0;
      if (typeof valA === "number" && typeof valB === "number") comp = valA - valB;
      else comp = String(valA).localeCompare(String(valB), undefined, { numeric: true });
      return sortDir === "asc" ? comp : -comp;
    });
  }, [filteredData, sortKey, sortDir]);

  const totalPages = Math.max(1, Math.ceil(sortedData.length / pageSize));
  const page = Math.min(currentPage, totalPages);
  const paginatedData = React.useMemo(() => {
    const start = (page - 1) * pageSize;
    return sortedData.slice(start, start + pageSize);
  }, [sortedData, page, pageSize]);

  const allPageKeys = React.useMemo(() => paginatedData.map((row) => row[keyField]), [paginatedData, keyField]);
  const isAllPageSelected = allPageKeys.length > 0 && allPageKeys.every((k) => selectedKeys.includes(k));

  const toggleSelectAll = () => {
    if (isAllPageSelected) {
      setSelectedKeys(selectedKeys.filter((k) => !allPageKeys.includes(k)));
    } else {
      setSelectedKeys(Array.from(new Set([...selectedKeys, ...allPageKeys])));
    }
  };

  const toggleSelectRow = (key: any) => {
    if (selectedKeys.includes(key)) {
      setSelectedKeys(selectedKeys.filter((k) => k !== key));
    } else {
      setSelectedKeys([...selectedKeys, key]);
    }
  };

  const selectedRows = React.useMemo(() => data.filter((r) => selectedKeys.includes(r[keyField])), [data, selectedKeys, keyField]);

  return (
    <div className={cn("space-y-3 w-full", className)}>
      <div className="flex items-center justify-between gap-4">
        {searchable && (
          <input
            type="text"
            className="flex h-9 w-64 rounded-md border border-input bg-background px-3 py-1 text-sm shadow-xs outline-hidden focus:ring-1 focus:ring-ring"
            placeholder={searchPlaceholder}
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setCurrentPage(1);
            }}
          />
        )}

        {selectable && selectedKeys.length > 0 && (
          <div className="flex items-center gap-3 px-3 py-1 bg-muted rounded-md text-xs font-mono">
            <span className="text-primary font-bold">{selectedKeys.length} selected</span>
            {renderBulkActions && renderBulkActions(selectedRows)}
          </div>
        )}
      </div>

      <div className="rounded-lg border border-border bg-card shadow-xs overflow-auto">
        <table className="w-full text-sm border-collapse text-left">
          <thead className="border-b border-border bg-muted/40 font-mono text-xs text-muted-foreground uppercase">
            <tr>
              {selectable && (
                <th className="p-3 w-10 text-center">
                  <input
                    type="checkbox"
                    checked={isAllPageSelected}
                    onChange={toggleSelectAll}
                    className="h-3.5 w-3.5 accent-primary"
                  />
                </th>
              )}
              {columns.map((col, idx) => (
                <th
                  key={idx}
                  style={{ width: col.width, textAlign: col.align || "left" }}
                  className={cn("p-3 font-semibold", col.sortable && "cursor-pointer select-none hover:text-foreground")}
                  onClick={() => {
                    if (!col.sortable || !col.accessor) return;
                    if (sortKey === col.accessor) {
                      if (sortDir === "asc") setSortDir("desc");
                      else if (sortDir === "desc") { setSortDir(null); setSortKey(null); }
                      else setSortDir("asc");
                    } else {
                      setSortKey(col.accessor);
                      setSortDir("asc");
                    }
                  }}
                >
                  {col.header}
                  {col.sortable && col.accessor === sortKey && (
                    <span className="ml-1 text-primary">{sortDir === "asc" ? "▲" : "▼"}</span>
                  )}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {paginatedData.length === 0 ? (
              <tr>
                <td colSpan={columns.length + (selectable ? 1 : 0)} className="p-8 text-center text-xs text-muted-foreground">
                  {emptyText}
                </td>
              </tr>
            ) : (
              paginatedData.map((row, rIdx) => {
                const rowKey = row[keyField] ?? rIdx;
                const isSelected = selectedKeys.includes(rowKey);
                return (
                  <tr key={String(rowKey)} className={cn("border-b border-border/60 hover:bg-muted/30 transition-colors", isSelected && "bg-muted/40")}>
                    {selectable && (
                      <td className="p-3 text-center">
                        <input
                          type="checkbox"
                          checked={isSelected}
                          onChange={() => toggleSelectRow(rowKey)}
                          className="h-3.5 w-3.5 accent-primary"
                        />
                      </td>
                    )}
                    {columns.map((col, cIdx) => (
                      <td key={cIdx} style={{ textAlign: col.align || "left" }} className={cn("p-3 text-foreground", dense && "py-2")}>
                        {col.render ? col.render(row, rIdx) : col.accessor ? row[col.accessor] : null}
                      </td>
                    ))}
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {totalPages > 1 && (
        <div className="flex items-center justify-between text-xs font-mono text-muted-foreground">
          <span>Page {page} of {totalPages} ({sortedData.length} records)</span>
          <div className="flex gap-2">
            <button
              type="button"
              disabled={page <= 1}
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
              className="px-2.5 py-1 rounded border border-input bg-background hover:bg-muted disabled:opacity-40"
            >
              Previous
            </button>
            <button
              type="button"
              disabled={page >= totalPages}
              onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
              className="px-2.5 py-1 rounded border border-input bg-background hover:bg-muted disabled:opacity-40"
            >
              Next
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
